function addTag(list, tag) {
  if (list.includes(tag)) throw new Error("Tag already added");
  list.push(tag);
  return list;
}

function rateFor(codes, code) {
  const rate = codes[code];
  if (rate === undefined) throw new Error("Unknown discount code");
  return rate;
}

function afterDiscount(total, percent) {
  return total * (100 - percent) / 100;
}

function useCode(order, code) {
  if (order.appliedDiscounts.includes(code)) throw new Error("Discount already applied");
  order.appliedDiscounts.push(code);
  return order;
}

