const codes = { SAVE10: 10, SAVE20: 20 };

function applyDiscount(order, code) {
  const rate = codes[code];
  if (rate === undefined) throw new Error("Unknown discount code");
  if (order.appliedDiscounts.length >= 2) throw new Error("Discount limit reached");
  order.appliedDiscounts.push(code);
  order.total = order.total * (100 - rate) / 100;
  return order;
}
